import {
  CircleAlert,
  CircleCheck,
  Info,
  TriangleAlert,
  X,
  type LucideIcon,
} from 'lucide-react'
import * as React from 'react'

import { cx } from '~/lib/cx'
import styles from './alert.module.scss'

export type AlertVariant = 'info' | 'success' | 'warning' | 'error'

const VARIANT: Record<AlertVariant, string> = {
  info: styles.info,
  success: styles.success,
  warning: styles.warning,
  error: styles.error,
}

const ICON: Record<AlertVariant, LucideIcon> = {
  info: Info,
  success: CircleCheck,
  warning: TriangleAlert,
  error: CircleAlert,
}

export interface AlertProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, 'title'> {
  variant?: AlertVariant
  title?: React.ReactNode
  /** Hide the tone icon. */
  hideIcon?: boolean
  /** Render a close button. The caller owns visibility. */
  onDismiss?: () => void
  dismissLabel?: string
}

export function Alert({
  variant = 'info',
  title,
  hideIcon = false,
  onDismiss,
  dismissLabel = 'Dismiss',
  className,
  children,
  ...props
}: AlertProps) {
  const Icon = ICON[variant]

  return (
    <div
      role={variant === 'error' ? 'alert' : 'status'}
      className={cx(styles.root, VARIANT[variant], className)}
      {...props}
    >
      {hideIcon ? null : (
        <span className={styles.icon}>
          <Icon aria-hidden />
        </span>
      )}

      <div className={styles.body}>
        {title ? <p className={styles.title}>{title}</p> : null}
        {children ? <div className={styles.description}>{children}</div> : null}
      </div>

      {onDismiss ? (
        <button
          type="button"
          onClick={onDismiss}
          aria-label={dismissLabel}
          className={styles.dismiss}
        >
          <X aria-hidden />
        </button>
      ) : null}
    </div>
  )
}

@use 'styles' as vz;

.root {
  --alert-bg: #{vz.color('accent')};
  --alert-fg: #{vz.color('accent-foreground')};
  --alert-border: #{vz.color('border')};
  --alert-icon: #{vz.color('muted-foreground')};

  position: relative;
  display: flex;
  gap: vz.space(3);
  padding: vz.space(4);
  border: 1px solid var(--alert-border);
  border-radius: vz.radius('xl');
  background: var(--alert-bg);
  color: var(--alert-fg);
  animation: vz-alert-in 320ms vz.ease('out') both;

  @include vz.motion-reduce {
    animation: none;
  }
}

.info {
  --alert-bg: #{vz.color('info', 0.1)};
  --alert-border: #{vz.color('info', 0.3)};
  --alert-icon: #{vz.color('info')};
}

.success {
  --alert-bg: #{vz.color('success', 0.1)};
  --alert-border: #{vz.color('success', 0.3)};
  --alert-icon: #{vz.color('success')};
}

.warning {
  --alert-bg: #{vz.color('warning', 0.12)};
  --alert-border: #{vz.color('warning', 0.35)};
  --alert-icon: #{vz.color('warning')};
}

.error {
  --alert-bg: #{vz.color('destructive', 0.09)};
  --alert-border: #{vz.color('destructive', 0.3)};
  --alert-icon: #{vz.color('destructive')};
}

.icon {
  display: inline-flex;
  flex: none;
  color: var(--alert-icon);
  padding-top: 1px;

  svg {
    @include vz.icon(5);
  }
}

.body {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: vz.space(1);
  min-width: 0;
}

.title {
  margin: 0;
  font-size: vz.font-size('sm');
  font-weight: 600;
  line-height: 1.35;
}

.description {
  margin: 0;
  color: inherit;
  font-size: vz.font-size('sm');
  line-height: 1.5;
  opacity: 0.85;
}

.dismiss {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  width: vz.space(6);
  height: vz.space(6);
  margin: -#{vz.space(1)} -#{vz.space(1)} 0 0;
  border: 0;
  border-radius: vz.radius('sm');
  background: transparent;
  color: inherit;
  opacity: 0.6;
  cursor: pointer;
  transition:
    opacity vz.duration('fast') vz.ease('out'),
    background-color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    opacity: 1;
    background: vz.color('foreground', 0.06);
  }

  @include vz.focus-ring(2px, 2px, 0.5);

  svg {
    @include vz.icon(3.5);
  }
}

@keyframes vz-alert-in {
  from {
    opacity: 0;
    transform: translateY(-6px) scale(0.99);
  }

  to {
    opacity: 1;
    transform: none;
  }
}
